class Question < ApplicationRecord
  belongs_to :quiz
  validates :body, presence: { message: 'is required' }
  validate :check_options
  before_create { self.position = quiz.questions.maximum(:position).to_i + 1 }

  def options=(rows)
    super(rows.reject { |row| row['text'].blank? })
  end

  def move!(direction)
    transaction do
      reload
      siblings = quiz.questions.reorder(nil)
      neighbor = case direction
      when 'up' then siblings.where(position: ...position).order(position: :desc).first
      when 'down' then siblings.where('position > ?', position).order(:position).first
